import { expect, test, uniqueName } from "../../fixtures";

test.describe("Manage vendors", () => {
  test(
    "the same vendor name is allowed in a different tenant",
    { tag: "@VEN-04" },
    async ({ apiAs }) => {
      // Arrange: a vendor with the same name already exists in another tenant.
      // Unique name keeps parallel runs and re-runs from colliding.
      const name = uniqueName("Acme Freight");
      const otherTenantMember = await apiAs("otherTenant");
      const existing = await otherTenantMember.post("/api/vendors", {
        data: {
          name,
          category: "logistics",
          contact_email: "ops@acmefreight.example",
        },
      });
      expect(existing.status(), "seed vendor in Globex tenant").toBe(201);

      // Act: the signed-in Northwind member creates a vendor with the same name.
      const member = await apiAs("member");
      const response = await member.post("/api/vendors", {
        data: {
          name,
          category: "logistics",
          contact_email: "ops@acmefreight.example",
        },
      });

      // Assert
      expect(response.status()).toBe(201);
      const created = await response.json();
      expect(created.name).toBe(name);
      expect(created.category).toBe("logistics");
      expect(created.contact_email).toBe("ops@acmefreight.example");
    },
  );
});
